mapper.select:
SELECT id, code, name, description, jurisdiction, embedding_model, doc_count, chunk_count,
       create_time, update_time
FROM kb_dataset WHERE id = #{id}

mapper.update:
UPDATE kb_dataset
name = #{name}, description = #{description}, jurisdiction = #{jurisdiction}, embedding_model = #{embeddingModel}, update_time = NOW()
WHERE id = #{id}

mapper.select:
SELECT COUNT(*) FROM kb_document

    dataset_id = #{datasetId}
    AND title ILIKE CONCAT('%', #{keyword}, '%')

SELECT d.id, d.dataset_id, s.name AS dataset_name, d.title, d.source_type, d.jurisdiction, d.effective_date, d.status, d.char_count, d.chunk_count, d.create_time, d.update_time FROM kb_document d LEFT JOIN kb_dataset s ON s.id = d.dataset_id
d.dataset_id = #{datasetId} AND d.title ILIKE CONCAT('%', #{keyword}, '%')
ORDER BY d.id DESC LIMIT #{limit} OFFSET #{offset}

SELECT id, dataset_id, title, source_type, jurisdiction, effective_date, status, content,
       char_count, chunk_count, create_time, update_time
FROM kb_document WHERE id = #{id}

SELECT c.id, c.dataset_id, c.document_id, d.title AS document_title, c.chunk_no, c.article_no,
       c.content, c.tokens,
       (

           CASE WHEN c.content ILIKE CONCAT('%', #{term}, '%') THEN 1 ELSE 0 END

       )::double precision / #{termCount} AS score
FROM kb_chunk c
LEFT JOIN kb_document d ON d.id = c.document_id
WHERE (

    c.content ILIKE CONCAT('%', #{term}, '%')

)
AND c.dataset_id = #{datasetId}
ORDER BY score DESC, c.id DESC
LIMIT #{limit}

SELECT COUNT(*) FROM legal_article
(content ILIKE CONCAT('%', #{keyword}, '%') OR title ILIKE CONCAT('%', #{keyword}, '%') OR law_name ILIKE CONCAT('%', #{keyword}, '%') OR article_no ILIKE CONCAT('%', #{keyword}, '%'))
AND jurisdiction = #{jurisdiction}

SELECT id, code, law_name, article_no, title, jurisdiction, effective_date, status, content, tags, version, create_time, update_time FROM legal_article
(content ILIKE CONCAT('%', #{keyword}, '%') OR title ILIKE CONCAT('%', #{keyword}, '%') OR law_name ILIKE CONCAT('%', #{keyword}, '%') OR article_no ILIKE CONCAT('%', #{keyword}, '%'))
AND jurisdiction = #{jurisdiction}
ORDER BY id DESC LIMIT #{limit} OFFSET #{offset}

SELECT id, code, law_name, article_no, title, jurisdiction, effective_date, status,
       content, tags, version, create_time, update_time
FROM legal_article WHERE id = #{id}

mapper.update:
UPDATE legal_article
code = #{article.code}, law_name = #{article.lawName}, article_no = #{article.articleNo}, title = #{article.title}, jurisdiction = #{article.jurisdiction}, effective_date = #{article.effectiveDate}, status = #{article.status}, content = #{article.content}, tags = #{article.tags}, version = #{article.version}, embedding = CAST(#{embedding} AS vector), update_time = NOW()
WHERE id = #{article.id}

